size_t count = ckh->count;
ckh->count = 0;
size_t nins = 0;

for (size_t i = 0; nins < count; i++) {
    if (aTab[i].key != nullptr) {
        const void *key = aTab[i].key;
        const void *data = aTab[i].data;

        if (ckh_try_insert(ckh, &key, &data)) {
            ckh->count = count;
            return true;
        }
        nins++;
    }
}

return false;

